package com.bank.nameformat;

import java.util.*;
import java.util.function.Function;
import java.util.logging.*;

public class AndThenDemo {
    private static final Logger log = Logger.getLogger("NameFormat");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(new Employee("Rajesh"), new Employee("priya"));
        NameFormatService service = new NameFormatService();

        List<String> shouted = service.upperNames(staff);
        log.info(() -> "Uppercase names: " + shouted);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/NameFormatService.java ───
class NameFormatService {
    // compose: extract name, THEN uppercase
    private final Function<Employee, String> upperName =
        ((Function<Employee, String>) Employee::getName)
            .andThen(String::toUpperCase);

    List<String> upperNames(List<Employee> staff) {
        return staff.stream()
            .map(upperName)        // one reusable composed function
            .toList();
    }
}
